/* The typed event name, for the slots that have no artwork behind them.
 *
 * `/brand.css` has already decided *whether* a name should be shown - it is
 * generated by the server, which is the only thing that can see what is in
 * `brand/`. This only fills in the words, so a page with no branding at all
 * never flashes a name it is about to hide, and a page with a wordmark never
 * paints one underneath it.
 *
 * Deliberately tiny and deliberately failure-tolerant: a venue network that
 * cannot answer this request leaves the screen exactly as the stylesheet drew
 * it, which is a finished screen. Nothing here is on the caption path.
 */
(function () {
  'use strict';

  var targets = document.querySelectorAll('.brand-eventname');
  if (!targets.length) { return; }

  fetch('/brand.json', { cache: 'no-store' })
    .then(function (response) {
      if (!response.ok) { throw new Error('brand.json: ' + response.status); }
      return response.json();
    })
    .then(function (brand) {
      var name = (brand && brand.event_name) || '';
      if (!name) { return; }
      for (var i = 0; i < targets.length; i++) {
        targets[i].textContent = name;
      }
      document.documentElement.setAttribute('data-brand-name', '1');
    })
    .catch(function () {
      /* Nothing to do and nothing to say. The stylesheet's own defaults are
         a complete screen; a missing name is just a missing name. */
    });
}());
